/**
 * Generates 10 products for a given category slug.
 * Uses the master catalog if available, otherwise generates sensible defaults.
 */
function generateProductsForCategory(categorySlug, shopId) {
  const catalog = PRODUCT_CATALOGS[categorySlug] || CATEGORY_PRODUCT_TEMPLATES[categorySlug];

  if (catalog) {
    return catalog.map((item, index) => ({
      shopId,
      name: item.name,
      slug: item.name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
      description: item.desc,
      brand: item.brand || null,
      pricePaise: item.price,
      mrpPaise: item.mrp,
      costPricePaise: Math.round(item.price * 0.7), // 30% margin assumption
      discountPercent: item.mrp > item.price ? Math.round(((item.mrp - item.price) / item.mrp) * 100) : 0,
      gstPercent: item.hsn ? (item.price > 100000 ? 18 : item.price > 50000 ? 12 : 5) : 0,
      unit: item.unit || 'piece',
      quantityPerUnit: item.qty || 1,
      stockQuantity: 20 + Math.floor(Math.random() * 180),
      lowStockThreshold: 5 + Math.floor(Math.random() * 15),
      maxOrderQuantity: Math.min(10, Math.max(1, Math.floor(item.qty || 1) * 3)),
      hsnCode: item.hsn || null,
      imageUrls: JSON.stringify([`https://cdn.localsampark.in/products/${categorySlug.toLowerCase()}_${index + 1}.webp`]),
      thumbnailUrl: `https://cdn.localsampark.in/products/${categorySlug.toLowerCase()}_${index + 1}_thumb.webp`,
      categoryPath: JSON.stringify([categorySlug.replace(/_/g, ' ')]),
      dietaryTags: JSON.stringify(item.tags || []),
      searchKeywords: JSON.stringify(item.keywords || []),
      isActive: true,
      isCustomizable: false,
      popularityScore: 30 + Math.floor(Math.random() * 70),
      displayOrder: index + 1,
    }));
  }

  // Fallback: generate generic products
  return Array.from({ length: 10 }, (_, i) => ({
    shopId,
    name: `${categorySlug.replace(/_/g, ' ')} Item ${i + 1}`,
    slug: `${categorySlug.toLowerCase()}-item-${i + 1}`,
    description: `Quality product from this ${categorySlug.replace(/_/g, ' ').toLowerCase()} shop.`,
    brand: null,
    pricePaise: (i + 1) * 10000 + Math.floor(Math.random() * 50000),
    mrpPaise: (i + 1) * 12000 + Math.floor(Math.random() * 50000),
    costPricePaise: (i + 1) * 7000,
    discountPercent: 10 + Math.floor(Math.random() * 20),
    gstPercent: 5,
    unit: 'piece',
    quantityPerUnit: 1,
    stockQuantity: 50 + Math.floor(Math.random() * 150),
    lowStockThreshold: 10,
    maxOrderQuantity: 5,
    hsnCode: null,
    imageUrls: JSON.stringify([`https://cdn.localsampark.in/products/${categorySlug.toLowerCase()}_${i + 1}.webp`]),
    thumbnailUrl: `https://cdn.localsampark.in/products/${categorySlug.toLowerCase()}_${i + 1}_thumb.webp`,
    categoryPath: JSON.stringify([categorySlug.replace(/_/g, ' ')]),
    dietaryTags: JSON.stringify([]),
    searchKeywords: JSON.stringify([categorySlug.toLowerCase().replace(/_/g, ' ')]),
    isActive: true,
    isCustomizable: false,
    popularityScore: 30 + Math.floor(Math.random() * 70),
    displayOrder: i + 1,
  }));
}

module.exports = {
  PRODUCT_CATALOGS,
  CATEGORY_PRODUCT_TEMPLATES,
  generateProductsForCategory,
};
